function allPairs(arr) {
  const result = [];
  for (let i = 0; i < arr.length; i++) {
    for (let j = i + 1; j < arr.length; j++) {
      result.push({ pair: [arr[i], arr[j]], diff: Math.abs(arr[i] - arr[j]) });
    }
  }
  return result;
}
